 2: # Role to build and deploy the Node.js sample modules for mod-auth
 3: - name: Build Node.js sample modules
 4:   npm: state=latest path={{ mod_auth_src_home }}/testing/{{ item }}
 5:   with_items:
 6:     - thing_module
 7:     - retrieve_module
 8: 
 9: - name: Load testing data
10:   command: mongoimport -d test -c {{ item.collection }} {{ mod_auth_src_home }}/testing/mongo/{{ item.file }}
11:   with_items:
12:     - { collection: users, file: users.json }
13:     - { collection: permissions, file: permissions.json }
14:     - { collection: credentials, file: credentials.json }

