 8: ---
 9: 
10: - name: (Deprecation) Catch and report renamed beeper-linkedin settings
11:   ansible.builtin.fail:
12:     msg: >-
13:       Your configuration contains a variable, which now has a different name.
14:       Please rename the variable (`{{ item.old }}` -> `{{ item.new }}`) on your configuration file (vars.yml).
15:   when: "lookup('ansible.builtin.varnames', ('^' + item.old + '$'), wantlist=True) | length > 0"
16:   with_items:
17:     - {'old': 'matrix_bridge_beeper_linkedin_login_shared_secret', 'new': '<superseded by matrix_bridge_beeper_linkedin_bridge_login_shared_secret_map_*>'}
18:     - {'old': 'matrix_bridge_beeper_linkedin_docker_image_name_prefix', 'new': 'matrix_bridge_beeper_linkedin_container_image_registry_prefix'}
19:     - {'old': 'matrix_bridge_beeper_linkedin_docker_image', 'new': 'matrix_bridge_beeper_linkedin_container_image'}
20:     - {'old': 'matrix_bridge_beeper_linkedin_docker_image_force_pull', 'new': 'matrix_bridge_beeper_linkedin_container_image_force_pull'}
21:     - {'old': 'matrix_bridge_beeper_linkedin_docker_image_registry_prefix', 'new': 'matrix_bridge_beeper_linkedin_container_image_registry_prefix'}
22:     - {'old': 'matrix_bridge_beeper_linkedin_docker_image_registry_prefix_upstream', 'new': 'matrix_bridge_beeper_linkedin_container_image_registry_prefix_upstream'}
23:     - {'old': 'matrix_bridge_beeper_linkedin_docker_image_registry_prefix_upstream_default', 'new': 'matrix_bridge_beeper_linkedin_container_image_registry_prefix_upstream_default'}
24:     - {'old': 'matrix_bridge_beeper_linkedin_docker_image_tag', 'new': 'matrix_bridge_beeper_linkedin_container_image_tag'}
25:     - {'old': 'matrix_bridge_beeper_linkedin_docker_src_files_path', 'new': 'matrix_bridge_beeper_linkedin_container_src_files_path'}
26:     - {'old': 'matrix_bridge_beeper_linkedin_container_image_force_pull', 'new': '<removed> (the new community.docker.docker_image_pull module handles this natively)'}
27: 
28: - name: Fail if required beeper-linkedin settings not defined
29:   ansible.builtin.fail:
30:     msg: >-
31:       You need to define a required configuration setting (`{{ item.name }}`).
32:   when: "item.when | bool and lookup('vars', item.name, default='') | string | length == 0"
33:   with_items:
34:     - {'name': 'matrix_bridge_beeper_linkedin_appservice_token', when: true}
35:     - {'name': 'matrix_bridge_beeper_linkedin_homeserver_address', when: true}
36:     - {'name': 'matrix_bridge_beeper_linkedin_homeserver_token', when: true}
37:     - {'name': 'matrix_bridge_beeper_linkedin_database_hostname', when: "{{ matrix_bridge_beeper_linkedin_database_engine == 'postgres' }}"}
38:     - {'name': 'matrix_bridge_beeper_linkedin_container_network', when: true}

